package main

import (
	"crypto/dsa"
	"crypto/rand"
	"crypto/rsa"
	"testing"
	"time"
)

func BenchmarkDSAKeyGeneration(b *testing.B) {
	for i := 0; i < b.N; i++ {
		privateKey, err := dsa.GenerateKey(dsa.ParameterGenerator(rand.Reader), rand.Reader)
		if err != nil {
			b.Fatal(err)
		}
		// Use the key to avoid compiler optimization
		_ = privateKey.Public()
	}
}

func BenchmarkRSAKeyGeneration(b *testing.B) {
	for i := 0; i < b.N; i++ {
		privateKey, err := rsa.GenerateKey(rand.Reader, 2048)
		if err != nil {
			b.Fatal(err)
		}
		// Use the key to avoid compiler optimization
		_ = privateKey.Public()
	}
}

func main() {
	start := time.Now()
	_, _ = dsa.GenerateKey(dsa.ParameterGenerator(rand.Reader), rand.Reader)
	dsaTime := time.Since(start)

	start = time.Now()
	_, _ = rsa.GenerateKey(rand.Reader, 2048)
	rsaTime := time.Since(start)

	println("DSA Key Generation Time:", dsaTime.String())
	println("RSA Key Generation Time:", rsaTime.String())
}
